<?php $title='Dashboard'; ?>
<section class="page-head"><div><h1>Visão geral</h1><p>Acompanhe a operação da GDA Plataforma.</p></div></section>
<div class="stats"><?php foreach([['Clientes',$stats['total_clients']],['Ativos',$stats['active_clients']],['Inativos',$stats['inactive_clients']],['Projetos',$stats['total_projects']],['Projetos ativos',$stats['active_projects']],['Módulos liberados',$stats['active_links']],['Versão',$version['version']],['Último backup',$lastBackup]] as $i=>$card): ?><article class="stat"><span><?= e($card[0]) ?></span><strong><?= e($card[1]) ?></strong></article><?php endforeach; ?></div>
<?php if($caixas): ?><section class="module-highlight"><div class="module-icon">▣</div><div><span>Módulo GDA</span><h2>Caixas</h2><p><?= e(project_status_label($caixas['status'])) ?> • v<?= e($caixas['version']) ?></p></div><a class="btn" href="<?= e(base_url('projetos/'.$caixas['id'])) ?>">Ver módulo</a></section><?php endif; ?>
<div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Últimos clientes</h2><a href="<?= e(base_url('clientes')) ?>">Ver todos</a></div><?php if(!$clients): ?><div class="empty">Nenhum cliente cadastrado.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Status</th><th>Cadastro</th></tr></thead><tbody><?php foreach($clients as $c): ?><tr><td><a href="<?= e(base_url('clientes/'.$c['id'])) ?>"><?= e($c['name']) ?></a><small><?= e($c['identifier']) ?></small></td><td><span class="badge <?= e($c['status']) ?>"><?= $c['status']==='active'?'Ativo':'Inativo' ?></span></td><td><?= e(date('d/m/Y',strtotime($c['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="panel"><div class="panel-head"><h2>Situação do sistema</h2></div><ul class="health"><li><span>Banco de dados</span><b class="ok">Conectado</b></li><?php foreach($folders as $f=>$ok): ?><li><span><?= e($f) ?></span><b class="<?= $ok?'ok':'bad' ?>"><?= $ok?'Gravável':'Sem permissão' ?></b></li><?php endforeach; ?></ul></section></div>
<section class="panel"><div class="panel-head"><h2>Atividades recentes</h2><a href="<?= e(base_url('logs')) ?>">Ver logs</a></div><?php if(!$logs): ?><div class="empty">Nenhuma atividade registrada.</div><?php else: ?><div class="timeline"><?php foreach($logs as $log): ?><div><span class="dot"></span><p><b><?= e($log['user_name']??'Sistema') ?></b> — <?= e($log['description']) ?><small><?= e(date('d/m/Y H:i',strtotime($log['created_at']))) ?></small></p></div><?php endforeach; ?></div><?php endif; ?></section>
